INSERT INTO REG_CLAUSES (CLAUSE_ID, REGULATION_ID, REGULATION_TITLE, CLAUSE, HEADING, TEXT, EFFECTIVE_DATE) VALUES
  ('NFCA-R01 §1.1', 'NFCA-R01', 'Operational Resilience Rule', '1.1', 'Purpose', 'This rule sets out the Authority''s requirements for important business services and the incidents that disrupt them.', '2025-03-31'),
  ('NFCA-R01 §1.2', 'NFCA-R01', 'Operational Resilience Rule', '1.2', 'Application', 'This rule applies to every firm authorised by the Authority, including branches that serve customers in its jurisdiction.', '2025-03-31'),
  ('NFCA-R01 §1.3', 'NFCA-R01', 'Operational Resilience Rule', '1.3', 'Definitions', 'In this rule, ''senior manager'' means an individual approved by the Authority to hold a senior management function.', '2025-03-31'),
  ('NFCA-R01 §1.4', 'NFCA-R01', 'Operational Resilience Rule', '1.4', 'Proportionality', 'A firm must apply this rule in a way that is proportionate to the nature, scale and complexity of its business.', '2025-03-31'),
  ('NFCA-R01 §3.1', 'NFCA-R01', 'Operational Resilience Rule', '3.1', 'Impact tolerance annual review', 'A firm must set an impact tolerance for each important business service and review it at least annually.', '2025-03-31'),
  ('NFCA-R01 §3.6', 'NFCA-R01', 'Operational Resilience Rule', '3.6', 'Impact tolerance annual review: evidence', 'A firm must keep evidence that it meets clause 3.1 and make that evidence available to the Authority on request.', '2025-03-31'),
  ('NFCA-R01 §4.2', 'NFCA-R01', 'Operational Resilience Rule', '4.2', 'Regulatory incident notification timeliness', 'A firm must notify the Authority of a major operational incident within 72 hours of determining that the incident is major.', '2025-03-31'),
  ('NFCA-R01 §4.7', 'NFCA-R01', 'Operational Resilience Rule', '4.7', 'Regulatory incident notification timeliness: evidence', 'A firm must keep evidence that it meets clause 4.2 and make that evidence available to the Authority on request.', '2025-03-31'),
  ('NFCA-R01 §5.1', 'NFCA-R01', 'Operational Resilience Rule', '5.1', 'Governance', 'A firm''s board is responsible for approving the policies that implement this rule and for overseeing their effectiveness.', '2025-03-31'),
  ('NFCA-R01 §5.2', 'NFCA-R01', 'Operational Resilience Rule', '5.2', 'Documentation', 'A firm must document how it meets each requirement of this rule and keep that documentation up to date.', '2025-03-31'),
  ('NFCA-R01 §5.3', 'NFCA-R01', 'Operational Resilience Rule', '5.3', 'Annual resilience scenario testing', 'A firm must test its ability to remain within impact tolerance through scenario testing at least annually.', '2025-03-31'),
  ('NFCA-R01 §5.8', 'NFCA-R01', 'Operational Resilience Rule', '5.8', 'Annual resilience scenario testing: evidence', 'A firm must keep evidence that it meets clause 5.3 and make that evidence available to the Authority on request.', '2025-03-31'),
  ('NFCA-R01 §6.1', 'NFCA-R01', 'Operational Resilience Rule', '6.1', 'Breaches', 'A firm must notify the Authority promptly if it becomes aware that it has breached this rule.', '2025-03-31'),
  ('NFCA-R01 §6.2', 'NFCA-R01', 'Operational Resilience Rule', '6.2', 'Transition', 'A firm must comply with this rule from its effective date unless the Authority has granted a written waiver.', '2025-03-31'),
  ('NFCA-R02 §1.1', 'NFCA-R02', 'Cybersecurity Requirements', '1.1', 'Purpose', 'This rule sets out the Authority''s requirements for information security controls over systems and data.', '2025-06-30'),
  ('NFCA-R02 §1.2', 'NFCA-R02', 'Cybersecurity Requirements', '1.2', 'Application', 'This rule applies to every firm authorised by the Authority, including branches that serve customers in its jurisdiction.', '2025-06-30'),
  ('NFCA-R02 §1.3', 'NFCA-R02', 'Cybersecurity Requirements', '1.3', 'Definitions', 'In this rule, ''senior manager'' means an individual approved by the Authority to hold a senior management function.', '2025-06-30'),
  ('NFCA-R02 §1.4', 'NFCA-R02', 'Cybersecurity Requirements', '1.4', 'Proportionality', 'A firm must apply this rule in a way that is proportionate to the nature, scale and complexity of its business.', '2025-06-30'),
  ('NFCA-R02 §3.4', 'NFCA-R02', 'Cybersecurity Requirements', '3.4', 'Multi-factor authentication coverage', 'A firm must require multi-factor authentication for all remote access to its systems and for all privileged accounts.', '2025-06-30'),
  ('NFCA-R02 §3.6', 'NFCA-R02', 'Cybersecurity Requirements', '3.6', 'Privileged access recertification', 'A firm must recertify privileged access rights at least quarterly.', '2025-06-30'),
  ('NFCA-R02 §3.9', 'NFCA-R02', 'Cybersecurity Requirements', '3.9', 'Multi-factor authentication coverage: evidence', 'A firm must keep evidence that it meets clause 3.4 and make that evidence available to the Authority on request.', '2025-06-30'),
  ('NFCA-R02 §3.11', 'NFCA-R02', 'Cybersecurity Requirements', '3.11', 'Privileged access recertification: evidence', 'A firm must keep evidence that it meets clause 3.6 and make that evidence available to the Authority on request.', '2025-06-30'),
  ('NFCA-R02 §4.1', 'NFCA-R02', 'Cybersecurity Requirements', '4.1', 'Critical patch remediation within 14 days', 'A firm must remediate critical security vulnerabilities on internet-facing systems within 14 days of a patch becoming available.', '2025-06-30'),
  ('NFCA-R02 §4.5', 'NFCA-R02', 'Cybersecurity Requirements', '4.5', 'Encryption of customer data', 'A firm must encrypt customer data at rest and in transit using industry-standard cryptography.', '2025-06-30'),
  ('NFCA-R02 §4.6', 'NFCA-R02', 'Cybersecurity Requirements', '4.6', 'Critical patch remediation within 14 days: evidence', 'A firm must keep evidence that it meets clause 4.1 and make that evidence available to the Authority on request.', '2025-06-30'),
  ('NFCA-R02 §4.10', 'NFCA-R02', 'Cybersecurity Requirements', '4.10', 'Encryption of customer data: evidence', 'A firm must keep evidence that it meets clause 4.5 and make that evidence available to the Authority on request.', '2025-06-30'),
  ('NFCA-R02 §5.1', 'NFCA-R02', 'Cybersecurity Requirements', '5.1', 'Governance', 'A firm''s board is responsible for approving the policies that implement this rule and for overseeing their effectiveness.', '2025-06-30'),
  ('NFCA-R02 §5.2', 'NFCA-R02', 'Cybersecurity Requirements', '5.2', 'Documentation', 'A firm must document how it meets each requirement of this rule and keep that documentation up to date.', '2025-06-30'),
  ('NFCA-R02 §6.1', 'NFCA-R02', 'Cybersecurity Requirements', '6.1', 'Breaches', 'A firm must notify the Authority promptly if it becomes aware that it has breached this rule.', '2025-06-30'),
  ('NFCA-R02 §6.2', 'NFCA-R02', 'Cybersecurity Requirements', '6.2', 'Transition', 'A firm must comply with this rule from its effective date unless the Authority has granted a written waiver.', '2025-06-30'),
  ('NFCA-R03 §1.1', 'NFCA-R03', 'Records and Retention Rule', '1.1', 'Purpose', 'This rule sets out the Authority''s requirements for the creation, retention and retrieval of business records.', '2024-12-31'),
  ('NFCA-R03 §1.2', 'NFCA-R03', 'Records and Retention Rule', '1.2', 'Application', 'This rule applies to every firm authorised by the Authority, including branches that serve customers in its jurisdiction.', '2024-12-31'),
  ('NFCA-R03 §1.3', 'NFCA-R03', 'Records and Retention Rule', '1.3', 'Definitions', 'In this rule, ''senior manager'' means an individual approved by the Authority to hold a senior management function.', '2024-12-31'),
  ('NFCA-R03 §1.4', 'NFCA-R03', 'Records and Retention Rule', '1.4', 'Proportionality', 'A firm must apply this rule in a way that is proportionate to the nature, scale and complexity of its business.', '2024-12-31'),
  ('NFCA-R03 §2.1', 'NFCA-R03', 'Records and Retention Rule', '2.1', 'Record retention period', 'A firm must retain records of customer transactions and communications for at least seven years.', '2024-12-31'),
  ('NFCA-R03 §2.4', 'NFCA-R03', 'Records and Retention Rule', '2.4', 'Regulatory record retrieval', 'A firm must be able to produce any retained record to the Authority within three business days of a request.', '2024-12-31'),
  ('NFCA-R03 §2.6', 'NFCA-R03', 'Records and Retention Rule', '2.6', 'Record retention period: evidence', 'A firm must keep evidence that it meets clause 2.1 and make that evidence available to the Authority on request.', '2024-12-31'),
  ('NFCA-R03 §2.9', 'NFCA-R03', 'Records and Retention Rule', '2.9', 'Regulatory record retrieval: evidence', 'A firm must keep evidence that it meets clause 2.4 and make that evidence available to the Authority on request.', '2024-12-31'),
  ('NFCA-R03 §3.2', 'NFCA-R03', 'Records and Retention Rule', '3.2', 'Immutable record storage', 'A firm must store retained records in a form that prevents alteration or deletion during the retention period.', '2024-12-31'),
  ('NFCA-R03 §3.7', 'NFCA-R03', 'Records and Retention Rule', '3.7', 'Immutable record storage: evidence', 'A firm must keep evidence that it meets clause 3.2 and make that evidence available to the Authority on request.', '2024-12-31'),
  ('NFCA-R03 §5.1', 'NFCA-R03', 'Records and Retention Rule', '5.1', 'Governance', 'A firm''s board is responsible for approving the policies that implement this rule and for overseeing their effectiveness.', '2024-12-31'),
  ('NFCA-R03 §5.2', 'NFCA-R03', 'Records and Retention Rule', '5.2', 'Documentation', 'A firm must document how it meets each requirement of this rule and keep that documentation up to date.', '2024-12-31'),
  ('NFCA-R03 §6.1', 'NFCA-R03', 'Records and Retention Rule', '6.1', 'Breaches', 'A firm must notify the Authority promptly if it becomes aware that it has breached this rule.', '2024-12-31'),
  ('NFCA-R03 §6.2', 'NFCA-R03', 'Records and Retention Rule', '6.2', 'Transition', 'A firm must comply with this rule from its effective date unless the Authority has granted a written waiver.', '2024-12-31'),
  ('NFCA-R04 §1.1', 'NFCA-R04', 'Third-Party Risk Rule', '1.1', 'Purpose', 'This rule sets out the Authority''s requirements for outsourcing and reliance on third-party service providers.', '2025-09-30'),
  ('NFCA-R04 §1.2', 'NFCA-R04', 'Third-Party Risk Rule', '1.2', 'Application', 'This rule applies to every firm authorised by the Authority, including branches that serve customers in its jurisdiction.', '2025-09-30'),
  ('NFCA-R04 §1.3', 'NFCA-R04', 'Third-Party Risk Rule', '1.3', 'Definitions', 'In this rule, ''senior manager'' means an individual approved by the Authority to hold a senior management function.', '2025-09-30'),
  ('NFCA-R04 §1.4', 'NFCA-R04', 'Third-Party Risk Rule', '1.4', 'Proportionality', 'A firm must apply this rule in a way that is proportionate to the nature, scale and complexity of its business.', '2025-09-30'),
  ('NFCA-R04 §2.2', 'NFCA-R04', 'Third-Party Risk Rule', '2.2', 'Pre-contract vendor due diligence', 'A firm must complete due diligence on a third-party service provider before entering into a contract.', '2025-09-30'),
  ('NFCA-R04 §2.7', 'NFCA-R04', 'Third-Party Risk Rule', '2.7', 'Pre-contract vendor due diligence: evidence', 'A firm must keep evidence that it meets clause 2.2 and make that evidence available to the Authority on request.', '2025-09-30'),
  ('NFCA-R04 §3.3', 'NFCA-R04', 'Third-Party Risk Rule', '3.3', 'Critical vendor periodic risk review', 'A firm must review the risk of each critical third-party service provider at least annually.', '2025-09-30'),
  ('NFCA-R04 §3.8', 'NFCA-R04', 'Third-Party Risk Rule', '3.8', 'Critical vendor periodic risk review: evidence', 'A firm must keep evidence that it meets clause 3.3 and make that evidence available to the Authority on request.', '2025-09-30'),
  ('NFCA-R04 §4.1', 'NFCA-R04', 'Third-Party Risk Rule', '4.1', 'Critical vendor exit plans', 'A firm must maintain a tested exit plan for each critical third-party service provider.', '2025-09-30'),
  ('NFCA-R04 §4.6', 'NFCA-R04', 'Third-Party Risk Rule', '4.6', 'Critical vendor exit plans: evidence', 'A firm must keep evidence that it meets clause 4.1 and make that evidence available to the Authority on request.', '2025-09-30'),
  ('NFCA-R04 §5.1', 'NFCA-R04', 'Third-Party Risk Rule', '5.1', 'Governance', 'A firm''s board is responsible for approving the policies that implement this rule and for overseeing their effectiveness.', '2025-09-30'),
  ('NFCA-R04 §5.2', 'NFCA-R04', 'Third-Party Risk Rule', '5.2', 'Documentation', 'A firm must document how it meets each requirement of this rule and keep that documentation up to date.', '2025-09-30'),
  ('NFCA-R04 §6.1', 'NFCA-R04', 'Third-Party Risk Rule', '6.1', 'Breaches', 'A firm must notify the Authority promptly if it becomes aware that it has breached this rule.', '2025-09-30'),
  ('NFCA-R04 §6.2', 'NFCA-R04', 'Third-Party Risk Rule', '6.2', 'Transition', 'A firm must comply with this rule from its effective date unless the Authority has granted a written waiver.', '2025-09-30'),
  ('NFCA-R05 §1.1', 'NFCA-R05', 'Complaints Handling Rule', '1.1', 'Purpose', 'This rule sets out the Authority''s requirements for the receipt, handling and resolution of customer complaints.', '2025-01-31'),
  ('NFCA-R05 §1.2', 'NFCA-R05', 'Complaints Handling Rule', '1.2', 'Application', 'This rule applies to every firm authorised by the Authority, including branches that serve customers in its jurisdiction.', '2025-01-31'),
  ('NFCA-R05 §1.3', 'NFCA-R05', 'Complaints Handling Rule', '1.3', 'Definitions', 'In this rule, ''senior manager'' means an individual approved by the Authority to hold a senior management function.', '2025-01-31'),
  ('NFCA-R05 §1.4', 'NFCA-R05', 'Complaints Handling Rule', '1.4', 'Proportionality', 'A firm must apply this rule in a way that is proportionate to the nature, scale and complexity of its business.', '2025-01-31'),
  ('NFCA-R05 §2.1', 'NFCA-R05', 'Complaints Handling Rule', '2.1', 'Complaint acknowledgement timeliness', 'A firm must acknowledge a customer complaint in writing within five business days of receipt.', '2025-01-31'),
  ('NFCA-R05 §2.3', 'NFCA-R05', 'Complaints Handling Rule', '2.3', 'Complaint final response within eight weeks', 'A firm must send a final response to a complaint within eight weeks of receipt.', '2025-01-31'),
  ('NFCA-R05 §2.6', 'NFCA-R05', 'Complaints Handling Rule', '2.6', 'Complaint acknowledgement timeliness: evidence', 'A firm must keep evidence that it meets clause 2.1 and make that evidence available to the Authority on request.', '2025-01-31'),
  ('NFCA-R05 §2.8', 'NFCA-R05', 'Complaints Handling Rule', '2.8', 'Complaint final response within eight weeks: evidence', 'A firm must keep evidence that it meets clause 2.3 and make that evidence available to the Authority on request.', '2025-01-31'),
  ('NFCA-R05 §3.1', 'NFCA-R05', 'Complaints Handling Rule', '3.1', 'Quarterly complaint root-cause analysis', 'A firm must analyse complaint root causes at least quarterly and report themes to senior management.', '2025-01-31'),
  ('NFCA-R05 §3.6', 'NFCA-R05', 'Complaints Handling Rule', '3.6', 'Quarterly complaint root-cause analysis: evidence', 'A firm must keep evidence that it meets clause 3.1 and make that evidence available to the Authority on request.', '2025-01-31'),
  ('NFCA-R05 §5.1', 'NFCA-R05', 'Complaints Handling Rule', '5.1', 'Governance', 'A firm''s board is responsible for approving the policies that implement this rule and for overseeing their effectiveness.', '2025-01-31'),
  ('NFCA-R05 §5.2', 'NFCA-R05', 'Complaints Handling Rule', '5.2', 'Documentation', 'A firm must document how it meets each requirement of this rule and keep that documentation up to date.', '2025-01-31'),
  ('NFCA-R05 §6.1', 'NFCA-R05', 'Complaints Handling Rule', '6.1', 'Breaches', 'A firm must notify the Authority promptly if it becomes aware that it has breached this rule.', '2025-01-31'),
  ('NFCA-R05 §6.2', 'NFCA-R05', 'Complaints Handling Rule', '6.2', 'Transition', 'A firm must comply with this rule from its effective date unless the Authority has granted a written waiver.', '2025-01-31'),
  ('NFCA-R06 §1.1', 'NFCA-R06', 'Anti-Money Laundering Program Rule', '1.1', 'Purpose', 'This rule sets out the Authority''s requirements for the firm''s anti-money laundering program.', '2024-06-30'),
  ('NFCA-R06 §1.2', 'NFCA-R06', 'Anti-Money Laundering Program Rule', '1.2', 'Application', 'This rule applies to every firm authorised by the Authority, including branches that serve customers in its jurisdiction.', '2024-06-30'),
  ('NFCA-R06 §1.3', 'NFCA-R06', 'Anti-Money Laundering Program Rule', '1.3', 'Definitions', 'In this rule, ''senior manager'' means an individual approved by the Authority to hold a senior management function.', '2024-06-30'),
  ('NFCA-R06 §1.4', 'NFCA-R06', 'Anti-Money Laundering Program Rule', '1.4', 'Proportionality', 'A firm must apply this rule in a way that is proportionate to the nature, scale and complexity of its business.', '2024-06-30'),
  ('NFCA-R06 §2.4', 'NFCA-R06', 'Anti-Money Laundering Program Rule', '2.4', 'High-risk customer due diligence refresh', 'A firm must refresh customer due diligence for high-risk customers at least annually.', '2024-06-30'),
  ('NFCA-R06 §2.9', 'NFCA-R06', 'Anti-Money Laundering Program Rule', '2.9', 'High-risk customer due diligence refresh: evidence', 'A firm must keep evidence that it meets clause 2.4 and make that evidence available to the Authority on request.', '2024-06-30'),
  ('NFCA-R06 §3.2', 'NFCA-R06', 'Anti-Money Laundering Program Rule', '3.2', 'Annual AML training completion', 'A firm must provide anti-money laundering training to relevant staff at least annually.', '2024-06-30'),
  ('NFCA-R06 §3.7', 'NFCA-R06', 'Anti-Money Laundering Program Rule', '3.7', 'Annual AML training completion: evidence', 'A firm must keep evidence that it meets clause 3.2 and make that evidence available to the Authority on request.', '2024-06-30'),
  ('NFCA-R06 §4.1', 'NFCA-R06', 'Anti-Money Laundering Program Rule', '4.1', 'Suspicious activity report timeliness', 'A firm must file a suspicious activity report within 30 days of determining that activity is suspicious.', '2024-06-30'),
  ('NFCA-R06 §4.6', 'NFCA-R06', 'Anti-Money Laundering Program Rule', '4.6', 'Suspicious activity report timeliness: evidence', 'A firm must keep evidence that it meets clause 4.1 and make that evidence available to the Authority on request.', '2024-06-30'),
  ('NFCA-R06 §5.1', 'NFCA-R06', 'Anti-Money Laundering Program Rule', '5.1', 'Governance', 'A firm''s board is responsible for approving the policies that implement this rule and for overseeing their effectiveness.', '2024-06-30'),
  ('NFCA-R06 §5.2', 'NFCA-R06', 'Anti-Money Laundering Program Rule', '5.2', 'Documentation', 'A firm must document how it meets each requirement of this rule and keep that documentation up to date.', '2024-06-30'),
  ('NFCA-R06 §6.1', 'NFCA-R06', 'Anti-Money Laundering Program Rule', '6.1', 'Breaches', 'A firm must notify the Authority promptly if it becomes aware that it has breached this rule.', '2024-06-30'),
  ('NFCA-R06 §6.2', 'NFCA-R06', 'Anti-Money Laundering Program Rule', '6.2', 'Transition', 'A firm must comply with this rule from its effective date unless the Authority has granted a written waiver.', '2024-06-30'),
  ('NFCA-R07 §1.1', 'NFCA-R07', 'Sanctions Compliance Rule', '1.1', 'Purpose', 'This rule sets out the Authority''s requirements for screening customers and payments against sanctions lists.', '2024-09-30'),
  ('NFCA-R07 §1.2', 'NFCA-R07', 'Sanctions Compliance Rule', '1.2', 'Application', 'This rule applies to every firm authorised by the Authority, including branches that serve customers in its jurisdiction.', '2024-09-30'),
  ('NFCA-R07 §1.3', 'NFCA-R07', 'Sanctions Compliance Rule', '1.3', 'Definitions', 'In this rule, ''senior manager'' means an individual approved by the Authority to hold a senior management function.', '2024-09-30'),
  ('NFCA-R07 §1.4', 'NFCA-R07', 'Sanctions Compliance Rule', '1.4', 'Proportionality', 'A firm must apply this rule in a way that is proportionate to the nature, scale and complexity of its business.', '2024-09-30'),
  ('NFCA-R07 §2.1', 'NFCA-R07', 'Sanctions Compliance Rule', '2.1', 'Sanctions screening at onboarding', 'A firm must screen every new customer against applicable sanctions lists before establishing the relationship.', '2024-09-30'),
  ('NFCA-R07 §2.3', 'NFCA-R07', 'Sanctions Compliance Rule', '2.3', 'Sanctions list update timeliness', 'A firm must apply updates to sanctions lists in its screening systems within 24 hours of publication.', '2024-09-30'),
  ('NFCA-R07 §2.6', 'NFCA-R07', 'Sanctions Compliance Rule', '2.6', 'Sanctions screening at onboarding: evidence', 'A firm must keep evidence that it meets clause 2.1 and make that evidence available to the Authority on request.', '2024-09-30'),
  ('NFCA-R07 §2.8', 'NFCA-R07', 'Sanctions Compliance Rule', '2.8', 'Sanctions list update timeliness: evidence', 'A firm must keep evidence that it meets clause 2.3 and make that evidence available to the Authority on request.', '2024-09-30'),
  ('NFCA-R07 §3.1', 'NFCA-R07', 'Sanctions Compliance Rule', '3.1', 'Payment sanctions screening', 'A firm must screen outgoing payments against sanctions lists before release.', '2024-09-30'),
  ('NFCA-R07 §3.6', 'NFCA-R07', 'Sanctions Compliance Rule', '3.6', 'Payment sanctions screening: evidence', 'A firm must keep evidence that it meets clause 3.1 and make that evidence available to the Authority on request.', '2024-09-30'),
  ('NFCA-R07 §5.1', 'NFCA-R07', 'Sanctions Compliance Rule', '5.1', 'Governance', 'A firm''s board is responsible for approving the policies that implement this rule and for overseeing their effectiveness.', '2024-09-30'),
  ('NFCA-R07 §5.2', 'NFCA-R07', 'Sanctions Compliance Rule', '5.2', 'Documentation', 'A firm must document how it meets each requirement of this rule and keep that documentation up to date.', '2024-09-30'),
