  ('NFCA-R08 §1.1', 'NFCA-R08', 'Model Risk Management Rule', '1.1', 'Purpose', 'This rule sets out the Authority''s requirements for models used in decisions, pricing, risk and reporting.', '2025-12-31'),
  ('NFCA-R08 §1.2', 'NFCA-R08', 'Model Risk Management Rule', '1.2', 'Application', 'This rule applies to every firm authorised by the Authority, including branches that serve customers in its jurisdiction.', '2025-12-31'),
  ('NFCA-R08 §1.3', 'NFCA-R08', 'Model Risk Management Rule', '1.3', 'Definitions', 'In this rule, ''senior manager'' means an individual approved by the Authority to hold a senior management function.', '2025-12-31'),
  ('NFCA-R08 §1.4', 'NFCA-R08', 'Model Risk Management Rule', '1.4', 'Proportionality', 'A firm must apply this rule in a way that is proportionate to the nature, scale and complexity of its business.', '2025-12-31'),
  ('NFCA-R08 §2.1', 'NFCA-R08', 'Model Risk Management Rule', '2.1', 'Model inventory completeness', 'A firm must maintain a complete inventory of models with an accountable owner for each.', '2025-12-31'),
  ('NFCA-R08 §2.6', 'NFCA-R08', 'Model Risk Management Rule', '2.6', 'Model inventory completeness: evidence', 'A firm must keep evidence that it meets clause 2.1 and make that evidence available to the Authority on request.', '2025-12-31'),
  ('NFCA-R08 §3.1', 'NFCA-R08', 'Model Risk Management Rule', '3.1', 'Annual validation of high-materiality models', 'A firm must independently validate each high-materiality model before use and at least annually thereafter.', '2025-12-31'),
  ('NFCA-R08 §3.6', 'NFCA-R08', 'Model Risk Management Rule', '3.6', 'Annual validation of high-materiality models: evidence', 'A firm must keep evidence that it meets clause 3.1 and make that evidence available to the Authority on request.', '2025-12-31'),
  ('NFCA-R08 §5.1', 'NFCA-R08', 'Model Risk Management Rule', '5.1', 'Governance', 'A firm''s board is responsible for approving the policies that implement this rule and for overseeing their effectiveness.', '2025-12-31'),
  ('NFCA-R08 §5.2', 'NFCA-R08', 'Model Risk Management Rule', '5.2', 'Documentation', 'A firm must document how it meets each requirement of this rule and keep that documentation up to date.', '2025-12-31'),
  ('NFCA-R08 §6.1', 'NFCA-R08', 'Model Risk Management Rule', '6.1', 'Breaches', 'A firm must notify the Authority promptly if it becomes aware that it has breached this rule.', '2025-12-31'),
  ('NFCA-R08 §6.2', 'NFCA-R08', 'Model Risk Management Rule', '6.2', 'Transition', 'A firm must comply with this rule from its effective date unless the Authority has granted a written waiver.', '2025-12-31'),
  ('NFCA-R09 §1.1', 'NFCA-R09', 'Customer Data Privacy Rule', '1.1', 'Purpose', 'This rule sets out the Authority''s requirements for the processing and protection of customer personal data.', '2025-04-30'),
  ('NFCA-R09 §1.2', 'NFCA-R09', 'Customer Data Privacy Rule', '1.2', 'Application', 'This rule applies to every firm authorised by the Authority, including branches that serve customers in its jurisdiction.', '2025-04-30'),
  ('NFCA-R09 §1.3', 'NFCA-R09', 'Customer Data Privacy Rule', '1.3', 'Definitions', 'In this rule, ''senior manager'' means an individual approved by the Authority to hold a senior management function.', '2025-04-30'),
  ('NFCA-R09 §1.4', 'NFCA-R09', 'Customer Data Privacy Rule', '1.4', 'Proportionality', 'A firm must apply this rule in a way that is proportionate to the nature, scale and complexity of its business.', '2025-04-30'),
  ('NFCA-R09 §3.3', 'NFCA-R09', 'Customer Data Privacy Rule', '3.3', 'Data access request timeliness', 'A firm must respond to a customer''s request for access to their personal data within 30 days.', '2025-04-30'),
  ('NFCA-R09 §3.8', 'NFCA-R09', 'Customer Data Privacy Rule', '3.8', 'Data access request timeliness: evidence', 'A firm must keep evidence that it meets clause 3.3 and make that evidence available to the Authority on request.', '2025-04-30'),
  ('NFCA-R09 §4.2', 'NFCA-R09', 'Customer Data Privacy Rule', '4.2', 'Customer breach notification', 'A firm must inform affected customers of a personal data breach that is likely to cause them harm without undue delay.', '2025-04-30'),
  ('NFCA-R09 §4.7', 'NFCA-R09', 'Customer Data Privacy Rule', '4.7', 'Customer breach notification: evidence', 'A firm must keep evidence that it meets clause 4.2 and make that evidence available to the Authority on request.', '2025-04-30'),
  ('NFCA-R09 §5.1', 'NFCA-R09', 'Customer Data Privacy Rule', '5.1', 'Governance', 'A firm''s board is responsible for approving the policies that implement this rule and for overseeing their effectiveness.', '2025-04-30'),
  ('NFCA-R09 §5.2', 'NFCA-R09', 'Customer Data Privacy Rule', '5.2', 'Documentation', 'A firm must document how it meets each requirement of this rule and keep that documentation up to date.', '2025-04-30'),
  ('NFCA-R09 §6.1', 'NFCA-R09', 'Customer Data Privacy Rule', '6.1', 'Breaches', 'A firm must notify the Authority promptly if it becomes aware that it has breached this rule.', '2025-04-30'),
  ('NFCA-R09 §6.2', 'NFCA-R09', 'Customer Data Privacy Rule', '6.2', 'Transition', 'A firm must comply with this rule from its effective date unless the Authority has granted a written waiver.', '2025-04-30'),
  ('NFCA-R10 §1.1', 'NFCA-R10', 'Suitability and Disclosure Rule', '1.1', 'Purpose', 'This rule sets out the Authority''s requirements for advice, product suitability and client disclosures.', '2025-07-31'),
  ('NFCA-R10 §1.2', 'NFCA-R10', 'Suitability and Disclosure Rule', '1.2', 'Application', 'This rule applies to every firm authorised by the Authority, including branches that serve customers in its jurisdiction.', '2025-07-31'),
  ('NFCA-R10 §1.3', 'NFCA-R10', 'Suitability and Disclosure Rule', '1.3', 'Definitions', 'In this rule, ''senior manager'' means an individual approved by the Authority to hold a senior management function.', '2025-07-31'),
  ('NFCA-R10 §1.4', 'NFCA-R10', 'Suitability and Disclosure Rule', '1.4', 'Proportionality', 'A firm must apply this rule in a way that is proportionate to the nature, scale and complexity of its business.', '2025-07-31'),
  ('NFCA-R10 §2.2', 'NFCA-R10', 'Suitability and Disclosure Rule', '2.2', 'Annual suitability review', 'A firm must review the suitability of ongoing advice for each advised client at least annually.', '2025-07-31'),
  ('NFCA-R10 §2.7', 'NFCA-R10', 'Suitability and Disclosure Rule', '2.7', 'Annual suitability review: evidence', 'A firm must keep evidence that it meets clause 2.2 and make that evidence available to the Authority on request.', '2025-07-31'),
  ('NFCA-R10 §3.1', 'NFCA-R10', 'Suitability and Disclosure Rule', '3.1', 'Pre-advice cost disclosure', 'A firm must give a client a written disclosure of all costs and charges before providing advice.', '2025-07-31'),
  ('NFCA-R10 §3.6', 'NFCA-R10', 'Suitability and Disclosure Rule', '3.6', 'Pre-advice cost disclosure: evidence', 'A firm must keep evidence that it meets clause 3.1 and make that evidence available to the Authority on request.', '2025-07-31'),
