  ('NFCA-R12 §1.2', 'NFCA-R12', 'Governance and Accountability Rule', '1.2', 'Application', 'This rule applies to every firm authorised by the Authority, including branches that serve customers in its jurisdiction.', '2024-12-31'),
  ('NFCA-R12 §1.3', 'NFCA-R12', 'Governance and Accountability Rule', '1.3', 'Definitions', 'In this rule, ''senior manager'' means an individual approved by the Authority to hold a senior management function.', '2024-12-31'),
  ('NFCA-R12 §1.4', 'NFCA-R12', 'Governance and Accountability Rule', '1.4', 'Proportionality', 'A firm must apply this rule in a way that is proportionate to the nature, scale and complexity of its business.', '2024-12-31'),
  ('NFCA-R12 §2.3', 'NFCA-R12', 'Governance and Accountability Rule', '2.3', 'Quarterly board compliance reporting', 'A firm''s board must receive a compliance report at least quarterly.', '2024-12-31'),
  ('NFCA-R12 §2.8', 'NFCA-R12', 'Governance and Accountability Rule', '2.8', 'Quarterly board compliance reporting: evidence', 'A firm must keep evidence that it meets clause 2.3 and make that evidence available to the Authority on request.', '2024-12-31'),
