INSERT INTO POLICY_SECTIONS (SECTION_ID, POLICY_ID, POLICY_TITLE, SECTION, HEADING, TEXT, OWNER) VALUES
  ('POL-01 §1', 'POL-01', 'Compliance Governance Policy', '1', 'Purpose', 'This policy describes how Harborline Bank (fictional) meets its obligations for board oversight and senior management accountability.', 'Chief Compliance Officer'),
  ('POL-01 §2', 'POL-01', 'Compliance Governance Policy', '2', 'Scope', 'This policy applies to all employees, contractors and business units of Harborline Bank (fictional), including Retail Banking, Wealth Management and Payments.', 'Chief Compliance Officer'),
  ('POL-01 §3', 'POL-01', 'Compliance Governance Policy', '3', 'Standards', 'Business units follow the procedures in this policy for board oversight and senior management accountability, and record evidence in the control library.', 'Chief Compliance Officer'),
  ('POL-01 §4', 'POL-01', 'Compliance Governance Policy', '4', 'Quarterly board compliance reporting', 'The Chief Compliance Officer reports to the board every quarter.', 'Chief Compliance Officer'),
  ('POL-01 §5', 'POL-01', 'Compliance Governance Policy', '5', 'Senior manager responsibilities map', 'A responsibilities map assigns every regulatory obligation to a named senior manager and is kept current.', 'Chief Compliance Officer'),
  ('POL-01 §6', 'POL-01', 'Compliance Governance Policy', '6', 'Roles and responsibilities', 'The Chief Compliance Officer owns this policy. Business unit heads are accountable for applying it in their areas.', 'Chief Compliance Officer'),
  ('POL-01 §7', 'POL-01', 'Compliance Governance Policy', '7', 'Exceptions', 'Exceptions to this policy require written approval from the Chief Compliance Officer and are recorded in the exceptions register.', 'Chief Compliance Officer'),
  ('POL-01 §8', 'POL-01', 'Compliance Governance Policy', '8', 'Monitoring', 'Compliance with this policy is tested by the second line of defence, and results are reported to the Risk Committee.', 'Chief Compliance Officer'),
  ('POL-01 §9', 'POL-01', 'Compliance Governance Policy', '9', 'Review', 'The Chief Compliance Officer reviews this policy at least annually and after any material regulatory change.', 'Chief Compliance Officer'),
  ('POL-02 §1', 'POL-02', 'Operational Resilience Policy', '1', 'Purpose', 'This policy describes how Harborline Bank (fictional) meets its obligations for important business services and the incidents that disrupt them.', 'Head of Resilience'),
  ('POL-02 §2', 'POL-02', 'Operational Resilience Policy', '2', 'Scope', 'This policy applies to all employees, contractors and business units of Harborline Bank (fictional), including Retail Banking, Wealth Management and Payments.', 'Head of Resilience'),
  ('POL-02 §3', 'POL-02', 'Operational Resilience Policy', '3', 'Impact tolerance annual review', 'Each important business service has an approved impact tolerance that the Resilience Office reviews at least annually.', 'Head of Resilience'),
