-- Regulatory Q&A desk on a Snowflake-managed MCP server
-- Synthetic data only: the regulator, the bank, its policies and its test results are fictional.
-- Run top to bottom as ACCOUNTADMIN (or a role that can create databases, warehouses, roles and grants).
-- Replace <YOUR_USER> with the Snowflake user who will run the app, and <YOUR_ORG>-<YOUR_ACCOUNT> in the app step.
-- If you run it with the Snowflake CLI, add --enable-templating NONE (the script contains & and <% characters).
-- The data blocks are generated by scripts/make_sql.py from regqa/data.py; edit the generator, not this file.

-- [step:setup]
USE ROLE ACCOUNTADMIN;
CREATE DATABASE IF NOT EXISTS REGQA_DEMO_DB COMMENT = 'Regulatory Q&A desk demo (synthetic data)';
CREATE SCHEMA IF NOT EXISTS REGQA_DEMO_DB.DESK;
CREATE WAREHOUSE IF NOT EXISTS REGQA_WH WAREHOUSE_SIZE = XSMALL AUTO_SUSPEND = 60 AUTO_RESUME = TRUE INITIALLY_SUSPENDED = TRUE;
USE SCHEMA REGQA_DEMO_DB.DESK;
USE WAREHOUSE REGQA_WH;

-- [step:tables]
-- Re-running the script starts the tables over; detach the policy first so CREATE OR REPLACE can succeed.
ALTER TABLE IF EXISTS CONTROL_TESTS DROP ALL ROW ACCESS POLICIES;
CREATE OR REPLACE TABLE REGULATIONS (REGULATION_ID STRING, TITLE STRING, REGULATOR STRING, EFFECTIVE_DATE DATE, SCOPE STRING);
CREATE OR REPLACE TABLE REG_CLAUSES (CLAUSE_ID STRING, REGULATION_ID STRING, REGULATION_TITLE STRING, CLAUSE STRING, HEADING STRING, TEXT STRING, EFFECTIVE_DATE DATE);
CREATE OR REPLACE TABLE POLICIES (POLICY_ID STRING, TITLE STRING, OWNER STRING, PRIMARY_REGULATION STRING, VERSION STRING, LAST_REVIEWED DATE);
CREATE OR REPLACE TABLE POLICY_SECTIONS (SECTION_ID STRING, POLICY_ID STRING, POLICY_TITLE STRING, SECTION STRING, HEADING STRING, TEXT STRING, OWNER STRING);
CREATE OR REPLACE TABLE CONTROLS (CONTROL_ID STRING, CONTROL_NAME STRING, POLICY_ID STRING, REGULATION_ID STRING, REQUIREMENT_KEY STRING, CLAUSE_ID STRING, SECTION_ID STRING);
CREATE OR REPLACE TABLE CONTROL_TESTS (TEST_ID STRING, CONTROL_ID STRING, CONTROL_NAME STRING, POLICY_ID STRING, REGULATION_ID STRING,
  BUSINESS_UNIT STRING, QUARTER STRING, QUARTER_END DATE, OWNER STRING, SAMPLE_SIZE NUMBER, EXCEPTIONS NUMBER, RESULT STRING);
CREATE OR REPLACE TABLE REMEDIATION_TICKETS (TICKET_ID STRING, OPENED_AT TIMESTAMP_NTZ, OPENED_BY STRING, OPENED_ROLE STRING,
  POLICY_SECTION_ID STRING, CLAUSE_ID STRING, SEVERITY STRING, SUMMARY STRING, STATUS STRING);
CREATE OR REPLACE TABLE MCP_AUDIT (EVENT_TS TIMESTAMP_NTZ, SESSION_ID STRING, ROLE_NAME STRING, METHOD STRING, TOOL STRING,
  ARGUMENTS VARIANT, STATUS STRING, LATENCY_MS NUMBER, RESULT_BYTES NUMBER, RESULT_PREVIEW STRING);

-- [step:data]
-- REGULATIONS: 12 rows

-- REG_CLAUSES: 160 rows

-- POLICIES: 20 rows

-- POLICY_SECTIONS: 180 rows

-- CONTROLS: 50 rows

-- CONTROL_TESTS: 600 rows

-- [step:search]
-- Two Cortex Search services: what the regulator requires, and what our policies say.
CREATE OR REPLACE CORTEX SEARCH SERVICE REG_SEARCH
  ON CHUNK
  ATTRIBUTES REGULATION_ID
  WAREHOUSE = REGQA_WH
  TARGET_LAG = '1 day'
  AS SELECT CLAUSE_ID, REGULATION_ID, REGULATION_TITLE, HEADING, TEXT,
            REGULATION_TITLE || ' ' || CLAUSE || ' ' || HEADING || ': ' || TEXT AS CHUNK
     FROM REG_CLAUSES;

CREATE OR REPLACE CORTEX SEARCH SERVICE POLICY_SEARCH
  ON CHUNK
  ATTRIBUTES POLICY_ID
  WAREHOUSE = REGQA_WH
  TARGET_LAG = '1 day'
  AS SELECT SECTION_ID, POLICY_ID, POLICY_TITLE, HEADING, TEXT, OWNER,
            POLICY_TITLE || ' section ' || SECTION || ' ' || HEADING || ': ' || TEXT AS CHUNK
     FROM POLICY_SECTIONS;

-- [step:semantic]
-- Cortex Analyst answers questions about control testing through this semantic view.
CREATE OR REPLACE SEMANTIC VIEW CONTROL_TESTS_SV
  TABLES (
    tests AS CONTROL_TESTS PRIMARY KEY (TEST_ID) COMMENT = 'One row per control test, per business unit, per quarter',
    controls AS CONTROLS PRIMARY KEY (CONTROL_ID) COMMENT = 'Controls in the control library',
    policies AS POLICIES PRIMARY KEY (POLICY_ID) COMMENT = 'Internal policies'
  )
  RELATIONSHIPS (
    tests_to_controls AS tests (CONTROL_ID) REFERENCES controls,
    controls_to_policies AS controls (POLICY_ID) REFERENCES policies
  )
  FACTS (
    tests.sample_size AS SAMPLE_SIZE COMMENT = 'Items sampled in the test',
    tests.exceptions AS EXCEPTIONS COMMENT = 'Items that failed the test',
    tests.is_fail AS IFF(RESULT = 'FAIL', 1, 0) COMMENT = '1 when the test failed'
  )
  DIMENSIONS (
    tests.business_unit AS BUSINESS_UNIT WITH SYNONYMS = ('BU', 'line of business', 'division'),
    tests.quarter AS QUARTER WITH SYNONYMS = ('period', 'test quarter') COMMENT = 'Calendar quarter, for example 2026-Q3',
    tests.quarter_end AS QUARTER_END COMMENT = 'Last day of the test quarter',
    tests.result AS RESULT COMMENT = 'PASS or FAIL',
    tests.test_owner AS OWNER WITH SYNONYMS = ('tester', 'control owner'),
    controls.control_id AS CONTROL_ID,
    controls.control_name AS CONTROL_NAME WITH SYNONYMS = ('control', 'control title'),
    controls.regulation_id AS REGULATION_ID WITH SYNONYMS = ('rule', 'regulation'),
    policies.policy_id AS POLICY_ID,
    policies.policy_title AS TITLE WITH SYNONYMS = ('policy', 'policy name'),
    policies.policy_owner AS OWNER COMMENT = 'Executive who owns the policy'
  )
  METRICS (
    tests.test_count AS COUNT(TEST_ID) WITH SYNONYMS = ('tests run', 'number of tests'),
    tests.failed_tests AS SUM(tests.is_fail) WITH SYNONYMS = ('failures', 'failed tests', 'exceptions found'),
    tests.failure_rate AS DIV0(SUM(tests.is_fail), COUNT(TEST_ID)) WITH SYNONYMS = ('fail rate', 'failure percentage')
      COMMENT = 'Share of tests that failed, between 0 and 1',
    tests.total_exceptions AS SUM(tests.exceptions) WITH SYNONYMS = ('exception count')
  )
  COMMENT = 'Control testing results for the fictional Harborline Bank';

-- [step:tools]
-- Custom tool 1: compare a regulation clause with a policy section. Read-only; uses Cortex AI.
CREATE OR REPLACE FUNCTION ASSESS_GAP(CLAUSE_REF STRING, SECTION_REF STRING)
  RETURNS VARIANT
  COMMENT = 'Compares one regulation clause with one policy section and returns a JSON verdict'
AS
$$
  SELECT AI_COMPLETE(
    model => 'llama3.3-70b',
    prompt => 'You are a bank compliance reviewer checking whether an internal POLICY meets a REGULATION.\n'
           || 'Step 1: if the two texts cover different obligations, answer NOT_RELATED.\n'
           || 'Step 2: otherwise extract the concrete requirement from each (deadline, frequency, retention period, scope) '
           || 'and convert to the same unit (72 hours = 3 days; quarterly = every 3 months; semi-annually = every 6 months; '
           || 'annually = every 12 months; 24 months = every 2 years).\n'
           || 'Step 3: answer GAP if the policy is weaker in any way: a longer deadline, a less frequent review, '
           || 'a shorter retention period, or narrower scope. Answer MEETS if it is the same or stricter.\n'
           || 'REGULATION ' || c.CLAUSE_ID || ': ' || c.TEXT || '\nPOLICY ' || p.SECTION_ID || ': ' || p.TEXT,
    response_format => {'type': 'json', 'schema': {'type': 'object', 'properties': {
        'regulation_requires': {'type': 'string'},
        'policy_says': {'type': 'string'},
        'verdict': {'type': 'string', 'enum': ['MEETS', 'GAP', 'NOT_RELATED']},
        'explanation': {'type': 'string'}},
      'required': ['regulation_requires', 'policy_says', 'verdict', 'explanation']}}
  )::VARIANT
  FROM REG_CLAUSES c, POLICY_SECTIONS p
  WHERE c.CLAUSE_ID = CLAUSE_REF AND p.SECTION_ID = SECTION_REF
$$;

-- Custom tool 2: open a remediation ticket. This one writes, so only the compliance lead gets it.
CREATE OR REPLACE PROCEDURE OPEN_REMEDIATION_TICKET(SECTION_ID STRING, CLAUSE_ID STRING, SEVERITY STRING, SUMMARY STRING)
  RETURNS STRING
  LANGUAGE SQL
  COMMENT = 'Opens a remediation ticket for a policy section that falls short of a regulation clause'
  EXECUTE AS CALLER
AS
$$
DECLARE
  ticket STRING;
BEGIN
  IF (:SEVERITY NOT IN ('HIGH', 'MEDIUM', 'LOW')) THEN
    RETURN 'Rejected: severity must be HIGH, MEDIUM or LOW.';
  END IF;
  ticket := 'REM-' || TO_CHAR(CURRENT_TIMESTAMP(), 'YYMMDD') || '-' || LPAD(UNIFORM(1, 9999, RANDOM())::STRING, 4, '0');
    SELECT :ticket, CURRENT_TIMESTAMP()::TIMESTAMP_NTZ, CURRENT_USER(), CURRENT_ROLE(), :SECTION_ID, :CLAUSE_ID, :SEVERITY, :SUMMARY, 'OPEN';
  RETURN 'Opened ' || ticket || ' (' || :SEVERITY || ') for ' || :SECTION_ID || ' against ' || :CLAUSE_ID;
END;
$$;

-- [step:mcp]
-- One MCP server, five tools. Any MCP client (this app, Claude, Cursor) discovers and calls them the same way.
CREATE OR REPLACE MCP SERVER REGQA_MCP FROM SPECIFICATION $$
tools:
  - title: "Regulation search"
    name: "regulation_search"
    type: "CORTEX_SEARCH_SERVICE_QUERY"
    identifier: "REGQA_DEMO_DB.DESK.REG_SEARCH"
    description: "Searches the clauses of the regulations the bank must follow. Returns CLAUSE_ID, REGULATION_TITLE, HEADING and TEXT."
  - title: "Policy search"
    name: "policy_search"
    type: "CORTEX_SEARCH_SERVICE_QUERY"
    identifier: "REGQA_DEMO_DB.DESK.POLICY_SEARCH"
    description: "Searches the sections of the bank's internal policies. Returns SECTION_ID, POLICY_TITLE, HEADING, TEXT and OWNER."
  - title: "Control testing analyst"
    name: "control_testing_analyst"
    type: "CORTEX_ANALYST_MESSAGE"
    identifier: "REGQA_DEMO_DB.DESK.CONTROL_TESTS_SV"
    description: "Answers questions about control test results, failures and failure rates by control, policy, business unit and quarter."
  - title: "Assess policy gap"
    name: "assess_gap"
    type: "GENERIC"
    identifier: "REGQA_DEMO_DB.DESK.ASSESS_GAP"
    description: "Compares one regulation clause with one policy section and returns MEETS, GAP or NOT_RELATED with an explanation."
    annotations:
      readOnlyHint: true
      destructiveHint: false
      idempotentHint: true
      openWorldHint: false
    config:
      type: "function"
      warehouse: "REGQA_WH"
      input_schema:
        type: "object"
        properties:
          clause_ref:
            type: "string"
            description: "Regulation clause id, for example 'NFCA-R01 §4.2'"
          section_ref:
            type: "string"
            description: "Policy section id, for example 'POL-07 §4'"
  - title: "Open remediation ticket"
    name: "open_remediation_ticket"
    type: "GENERIC"
    identifier: "REGQA_DEMO_DB.DESK.OPEN_REMEDIATION_TICKET"
    description: "Opens a remediation ticket for a policy section that falls short of a regulation clause. Writes a row; ask a person to approve first."
    annotations:
      readOnlyHint: false
      destructiveHint: false
      idempotentHint: false
      openWorldHint: false
    config:
      type: "procedure"
      warehouse: "REGQA_WH"
      input_schema:
        type: "object"
        properties:
          section_id:
            type: "string"
            description: "Policy section id"
          clause_id:
            type: "string"
            description: "Regulation clause id"
          severity:
            type: "string"
            description: "HIGH, MEDIUM or LOW"
          summary:
            type: "string"
            description: "One or two sentences describing the gap and the fix"
$$;

-- [step:roles]
-- Three roles. Access to the MCP server does not give access to its tools: each tool is granted separately.
CREATE ROLE IF NOT EXISTS REGQA_ANALYST COMMENT = 'Compliance analyst: read tools only, Retail Banking and Payments data';
CREATE ROLE IF NOT EXISTS REGQA_COMPLIANCE_LEAD COMMENT = 'Compliance lead: all tools, all business units';
CREATE ROLE IF NOT EXISTS REGQA_AUDITOR COMMENT = 'Internal audit: can reach the server but call no tools; reads the audit log';
GRANT ROLE REGQA_ANALYST TO ROLE SYSADMIN;
GRANT ROLE REGQA_COMPLIANCE_LEAD TO ROLE SYSADMIN;
GRANT ROLE REGQA_AUDITOR TO ROLE SYSADMIN;

GRANT USAGE ON WAREHOUSE REGQA_WH TO ROLE REGQA_ANALYST;
GRANT USAGE ON WAREHOUSE REGQA_WH TO ROLE REGQA_COMPLIANCE_LEAD;
GRANT USAGE ON WAREHOUSE REGQA_WH TO ROLE REGQA_AUDITOR;
GRANT USAGE ON DATABASE REGQA_DEMO_DB TO ROLE REGQA_ANALYST;
GRANT USAGE ON DATABASE REGQA_DEMO_DB TO ROLE REGQA_COMPLIANCE_LEAD;
GRANT USAGE ON DATABASE REGQA_DEMO_DB TO ROLE REGQA_AUDITOR;
GRANT USAGE ON SCHEMA REGQA_DEMO_DB.DESK TO ROLE REGQA_ANALYST;
GRANT USAGE ON SCHEMA REGQA_DEMO_DB.DESK TO ROLE REGQA_COMPLIANCE_LEAD;
GRANT USAGE ON SCHEMA REGQA_DEMO_DB.DESK TO ROLE REGQA_AUDITOR;
GRANT USAGE ON MCP SERVER REGQA_MCP TO ROLE REGQA_ANALYST;
GRANT USAGE ON MCP SERVER REGQA_MCP TO ROLE REGQA_COMPLIANCE_LEAD;
GRANT USAGE ON MCP SERVER REGQA_MCP TO ROLE REGQA_AUDITOR;
GRANT DATABASE ROLE SNOWFLAKE.CORTEX_USER TO ROLE REGQA_ANALYST;
GRANT DATABASE ROLE SNOWFLAKE.CORTEX_USER TO ROLE REGQA_COMPLIANCE_LEAD;
-- Model access (model RBAC): only the models these tools use.
-- llama3.3-70b runs ASSESS_GAP; claude-sonnet-4-5 is what Cortex Analyst needed in testing on AWS US East 1.
-- If Cortex Analyst reports that its models are not authorized in your region, see the README.
GRANT APPLICATION ROLE SNOWFLAKE."CORTEX-MODEL-ROLE-LLAMA3.3-70B" TO ROLE REGQA_ANALYST;
GRANT APPLICATION ROLE SNOWFLAKE."CORTEX-MODEL-ROLE-LLAMA3.3-70B" TO ROLE REGQA_COMPLIANCE_LEAD;
GRANT APPLICATION ROLE SNOWFLAKE."CORTEX-MODEL-ROLE-CLAUDE-SONNET-4-5" TO ROLE REGQA_ANALYST;
GRANT APPLICATION ROLE SNOWFLAKE."CORTEX-MODEL-ROLE-CLAUDE-SONNET-4-5" TO ROLE REGQA_COMPLIANCE_LEAD;

-- Read tools for the analyst and the lead
GRANT USAGE ON CORTEX SEARCH SERVICE REG_SEARCH TO ROLE REGQA_ANALYST;
GRANT USAGE ON CORTEX SEARCH SERVICE POLICY_SEARCH TO ROLE REGQA_ANALYST;
GRANT SELECT ON SEMANTIC VIEW CONTROL_TESTS_SV TO ROLE REGQA_ANALYST;
GRANT USAGE ON FUNCTION ASSESS_GAP(STRING, STRING) TO ROLE REGQA_ANALYST;
GRANT USAGE ON CORTEX SEARCH SERVICE REG_SEARCH TO ROLE REGQA_COMPLIANCE_LEAD;
GRANT USAGE ON CORTEX SEARCH SERVICE POLICY_SEARCH TO ROLE REGQA_COMPLIANCE_LEAD;
GRANT SELECT ON SEMANTIC VIEW CONTROL_TESTS_SV TO ROLE REGQA_COMPLIANCE_LEAD;
GRANT USAGE ON FUNCTION ASSESS_GAP(STRING, STRING) TO ROLE REGQA_COMPLIANCE_LEAD;
GRANT SELECT ON TABLE REG_CLAUSES TO ROLE REGQA_ANALYST;
GRANT SELECT ON TABLE POLICY_SECTIONS TO ROLE REGQA_ANALYST;
GRANT SELECT ON TABLE REG_CLAUSES TO ROLE REGQA_COMPLIANCE_LEAD;
GRANT SELECT ON TABLE POLICY_SECTIONS TO ROLE REGQA_COMPLIANCE_LEAD;
GRANT SELECT ON TABLE CONTROL_TESTS TO ROLE REGQA_ANALYST;
GRANT SELECT ON TABLE CONTROLS TO ROLE REGQA_ANALYST;
GRANT SELECT ON TABLE POLICIES TO ROLE REGQA_ANALYST;
GRANT SELECT ON TABLE CONTROL_TESTS TO ROLE REGQA_COMPLIANCE_LEAD;
GRANT SELECT ON TABLE CONTROLS TO ROLE REGQA_COMPLIANCE_LEAD;
GRANT SELECT ON TABLE POLICIES TO ROLE REGQA_COMPLIANCE_LEAD;

-- The write tool: compliance lead only
GRANT USAGE ON PROCEDURE OPEN_REMEDIATION_TICKET(STRING, STRING, STRING, STRING) TO ROLE REGQA_COMPLIANCE_LEAD;
GRANT INSERT, SELECT ON TABLE REMEDIATION_TICKETS TO ROLE REGQA_COMPLIANCE_LEAD;
GRANT SELECT ON TABLE REMEDIATION_TICKETS TO ROLE REGQA_ANALYST;
GRANT SELECT ON TABLE REMEDIATION_TICKETS TO ROLE REGQA_AUDITOR;

-- The app logs every MCP call it makes; everyone can append, only audit and the lead can read it all
GRANT INSERT ON TABLE MCP_AUDIT TO ROLE REGQA_ANALYST;
GRANT INSERT, SELECT ON TABLE MCP_AUDIT TO ROLE REGQA_COMPLIANCE_LEAD;
GRANT INSERT, SELECT ON TABLE MCP_AUDIT TO ROLE REGQA_AUDITOR;

GRANT ROLE REGQA_ANALYST TO USER <YOUR_USER>;
GRANT ROLE REGQA_COMPLIANCE_LEAD TO USER <YOUR_USER>;
GRANT ROLE REGQA_AUDITOR TO USER <YOUR_USER>;

-- [step:rowaccess]
-- Analysts see control tests for their business units only. The same rule applies whether the question
-- comes through SQL, Cortex Analyst, or an MCP client, because it lives on the table.
CREATE OR REPLACE TABLE BU_ACCESS (ROLE_NAME STRING, BUSINESS_UNIT STRING);

CREATE ROW ACCESS POLICY IF NOT EXISTS regqa_bu_policy AS (bu STRING) RETURNS BOOLEAN ->
  EXISTS (SELECT 1 FROM REGQA_DEMO_DB.DESK.BU_ACCESS a WHERE a.BUSINESS_UNIT = bu AND IS_ROLE_IN_SESSION(a.ROLE_NAME));
ALTER TABLE CONTROL_TESTS ADD ROW ACCESS POLICY regqa_bu_policy ON (BUSINESS_UNIT);

-- [step:app]
-- Optional: let the compliance lead own the Streamlit in Snowflake app, so the deployed app runs with the
-- lead's grants and nothing more. Then deploy with: snow streamlit deploy regqa_desk --role REGQA_COMPLIANCE_LEAD
-- Use your account's Streamlit compute pool and PyPI external access integration if their names differ.
GRANT CREATE STREAMLIT ON SCHEMA REGQA_DEMO_DB.DESK TO ROLE REGQA_COMPLIANCE_LEAD;
GRANT CREATE STAGE ON SCHEMA REGQA_DEMO_DB.DESK TO ROLE REGQA_COMPLIANCE_LEAD;
GRANT USAGE ON COMPUTE POOL SYSTEM_COMPUTE_POOL_CPU TO ROLE REGQA_COMPLIANCE_LEAD;
GRANT USAGE ON INTEGRATION PYPI_ACCESS_INTEGRATION TO ROLE REGQA_COMPLIANCE_LEAD;
-- The app calls this account's own MCP endpoint, so it needs egress to the account host (with hyphens, port 443).
-- Find it with: SELECT LOWER(REPLACE(CURRENT_ORGANIZATION_NAME() || '-' || CURRENT_ACCOUNT_NAME(), '_', '-')) || '.snowflakecomputing.com';
CREATE OR REPLACE NETWORK RULE REGQA_MCP_EGRESS MODE = EGRESS TYPE = HOST_PORT
  VALUE_LIST = ('<YOUR_ORG>-<YOUR_ACCOUNT>.snowflakecomputing.com:443');
CREATE OR REPLACE EXTERNAL ACCESS INTEGRATION REGQA_MCP_ACCESS
  ALLOWED_NETWORK_RULES = (REGQA_MCP_EGRESS) ENABLED = TRUE
  COMMENT = 'Lets the Regulatory QA desk app call its own account MCP endpoint';
GRANT USAGE ON INTEGRATION REGQA_MCP_ACCESS TO ROLE REGQA_COMPLIANCE_LEAD;

-- [step:verify]
USE SECONDARY ROLES NONE;
USE ROLE REGQA_ANALYST;
SELECT 'analyst sees' AS who, BUSINESS_UNIT, COUNT(*) AS tests FROM REGQA_DEMO_DB.DESK.CONTROL_TESTS GROUP BY 2 ORDER BY 2;
SELECT PARSE_JSON(SNOWFLAKE.CORTEX.SEARCH_PREVIEW('REGQA_DEMO_DB.DESK.REG_SEARCH',
  '{"query": "how quickly must we notify the regulator of a major incident", "columns": ["CLAUSE_ID", "TEXT"], "limit": 1}')):results[0] AS top_clause;
USE ROLE REGQA_COMPLIANCE_LEAD;
SELECT 'lead sees' AS who, BUSINESS_UNIT, COUNT(*) AS tests FROM REGQA_DEMO_DB.DESK.CONTROL_TESTS GROUP BY 2 ORDER BY 2;
SELECT REGQA_DEMO_DB.DESK.ASSESS_GAP('NFCA-R01 §4.2', 'POL-07 §4'):verdict::STRING AS verdict_planted_gap,
       REGQA_DEMO_DB.DESK.ASSESS_GAP('NFCA-R02 §3.4', 'POL-05 §3'):verdict::STRING AS verdict_compliant;
USE ROLE ACCOUNTADMIN;
USE SECONDARY ROLES ALL;
SHOW MCP SERVERS IN SCHEMA REGQA_DEMO_DB.DESK;

